    "26008": [
        {
            "key": 2766807234,
            "GroupId": 2600802,
            "id": 1,
            "number": 1,
            "title": {
                "cn": "瞧见了吧？我成功了！",
                "en": "",
                "kr": "보셨죠? 저 성공했어요!",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "静子突然把老师叫过来，兴奋地向老师展示着自己的百夜堂连锁经营战略有多么成功。但老师却在担心静子现在的状态。对于老师出乎意料的反应，静子感到有些慌张，最终逃跑了。",
                "en": "",
                "kr": "갑작스레 선생님을 불러낸 시즈코는 자신의 백야당 프랜차이즈화 사업이 얼마나 성공 가도를 달리고 있는지 신이 나서 설명한다. 그러나 시즈코가 어딘가 내몰려 있다는 인상을 받은 선생님은 오히려 그녀를 걱정해 주고, 예상 밖의 반응에 당황한 시즈코는 도망치고 만다.",
                "jp": "",
                "tw": "",
                "th": ""
            }
        },
        {
            "key": 1341349068,
            "GroupId": 2600803,
            "id": 2,
            "number": 2,
            "title": {
                "cn": "所以……是来做什么的？",
                "en": "",
                "kr": "그런데…… 무엇을 위해서였죠?",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "静子感觉有些烦恼，老师看出了这一点，主动提出要帮静子咨询。现在的静子太专注于连锁经营的成功，忘记了自己经营百夜堂的初心——顾客们的微笑。静子明白这一点后，终于再次振作起来。",
                "en": "",
                "kr": "어째서인지 풀이 죽어 있는 시즈코에게 선생님이 상담을 해 준다. 시즈코는 프랜차이즈 사업의 성공에 너무 몰두한 나머지, 자신이 원래 추구했던 가치- 손님들의 미소를 잊고 있었다. 시즈코는 뒤늦게 이 사실을 깨닫고 마음을 다잡는다.",
                "jp": "",
                "tw": "",
                "th": ""
            }
        },
        {
            "key": 1344506803,
            "GroupId": 2600805,
            "id": 3,
            "number": 3,
            "title": {
                "cn": "我可是很贪心的！",
                "en": "",
                "kr": "저는 엄~청난 욕심꾸러기니까요!",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "重新打起精神的静子和老师约好在海之家见面。静子向老师表达了谢意，并向老师诉说了自己的野心与梦想。",
                "en": "",
                "kr": "다시 기운을 되찾은 시즈코에게 불려 나온 선생님. 시즈코는 선생님에게 감사를 표하며, 자신의 새로운 야망과 꿈을 당당하게 이야기한다. ",
                "jp": "",
                "tw": "",
                "th": ""
            }
        }
    ],
    "26009": [
        {
            "key": 1746842993,
            "GroupId": 2600902,
            "id": 1,
            "number": 1,
            "title": {
                "cn": "工作参考",
                "en": "",
                "kr": "작업 레퍼런스",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "柚子为了给新游戏的开发当作参考而穿上了女仆装。但因为她天生自信心不足，认为自己不适合当模特，显得相当不安。老师鼓励垂头丧气的柚子，并且给予了特别的建议。",
                "en": "",
                "kr": "유즈는 새로 개발 중인 게임의 레퍼런스 참고를 위해 메이드복을 입게 된다. 하지만 타고난 자신감이 부족한 탓에 자신은 모델로는 적합하지 않다며 불안을 드러낸다. 선생님은 기가 죽은 유즈가 기운을 낼 수 있도록 응원하며 특별한 조언을 해준다.",
                "jp": "",
                "tw": "",
                "th": ""
            }
        },
        {
            "key": 831733757,
            "GroupId": 2600903,
            "id": 2,
            "number": 2,
            "title": {
                "cn": "新的兼职",
                "en": "",
                "kr": "새로운 아르바이트",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "老师在夏莱从容地办着公。过了一会儿，传来了急促的脚步声，柚子哭丧着脸来到了夏莱。原来，她发现老师安排的打工是女仆咖啡厅，就从咖啡厅逃走了。老师为了让柚子能适应打工环境，提议进行女仆特训。",
                "en": "",
                "kr": "샬레에서 한가로이 업무를 보던 선생님. 잠시 후 다급한 발소리와 함께 울상을 짓는 유즈가 샬레에 들어온다. 사연을 듣자하니 선생님이 주선해 준 아르바이트가 메이드 카페라는 사실을 깨닫고 카페에서 도망쳐 나온 것. 선생님은 유즈가 아르바이트에 잘 적응할 수 있도록 메이드 특훈을 제안한다.",
                "jp": "",
                "tw": "",
                "th": ""
            }
        },
        {
            "key": 2231433090,
            "GroupId": 2600905,
            "id": 3,
            "number": 3,
            "title": {
                "cn": "柜子里的不速之客",
                "en": "",
                "kr": "캐비닛 안의 불청객",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "外勤中的老师为了观察柚子的状况，于是前往她打工的女仆咖啡厅。老师的出现让柚子顿时很紧张，表现失常接连发生失误。过了一会，休息时间结束，柚子依旧没有回来。老师感到担心，于是去找柚子，结果看见了令人意外的一幕。",
                "en": "",
                "kr": "외근 중 선생님은 유즈의 상태를 보기 위해 그녀가 아르바이트를 하고 있는 메이드 카페로 향한다. 선생님의 방문에 잔뜩 긴장한 유즈는 평소와는 다르게 실수를 연발하고 만다. 잠시 후. 휴식 시간이 지나도 유즈가 돌아오지 않자 선생님은 걱정스러운 마음에 유즈를 찾아 나서고 의외의 광경을 마주한다.",
                "jp": "",
                "tw": "",
                "th": ""
            }
        },
        {
            "key": 1898965458,
            "GroupId": 2600906,
            "id": 4,
            "number": 4,
            "title": {
                "cn": "清理游戏开发部",
                "en": "",
                "kr": "게임개발부의 청소",
                "jp": "",
                "tw": "",
                "th": ""
            },
            "description": {
                "cn": "为了协助柚子做清洁，老师前往游戏开发部的活动室。但柚子说的清理并不是清理活动室，而是优化电脑。但看见房间一团乱的景象后，老师认为需要打扫，于是向柚子提议打扫活动室。",
                "en": "",
                "kr": "유즈의 청소를 돕기 위해 게임개발부 부실을 찾은 선생님. 하지만 유즈가 말한 청소는 부실 청소가 아닌, 컴퓨터의 최적화를 의미하는 것이었다. 하지만 어질러진 부실을 마주한 선생님은 청소의 필요성을 느끼고 유즈에게 부실 청소를 제안한다.",
                "jp": "",
                "tw": "",
                "th": ""
            }
        }
    ],
