                "en": "",
                "kr": "그간 선생에게 받은 도움의 보답을 하기 위해, 츠쿠요는 선생을 불러 식사를 대접한다. 그러면서 모델로서의 자신에 대한 생각을 선생에게 풀어 놓는다.",
