                "en": "",
                "kr": "케이의 밀레니엄 수업 참관을 가 보는 선생님. 그러나 케이는 모든 지식을 너무 잘 습득한 상태여서, 수업에는 큰 의미가 없었다. 선생님은 학교에 나와서 '잘 노는 것' 역시 학생에게는 필요한 일이라며, 케이가 학교에 나오는 의미를 일깨워 준다.",
                "jp": "",
