                "en": "",
                "kr": "버그가 너무 많다며 투덜거리는 모모톡을 보내오는 케이. 선생님이 어리둥절해하자, 케이는 마침 잘 되었다며 선생님을 게임개발부실로 부른다. 그렇게 둘은, 게임개발부가 만든 알파 버전 게임의 QA를 진행하게 된다.",
                "jp": "",
                "tw": "",
                "th": ""
