                "en": "",
                "kr": "게임개발부실의 청소를 하면서 오늘도 투덜거리는 케이. 그런데 선생님의 낌새가 조금 수상하다는 것을 알아차리고, 선생님은 평소에 잘 치우고 사느냐며 선생님을 추궁하는데……",
                "jp": "",
