                "en": "",
                "kr": "샬레에 당번으로 찾아온 케이. 수고했으니까 저녁 식사도 같이하고 액세서리 쇼핑도 가자는 선생님의 제안에, 케이는 부끄러워하면서도 기뻐한다.",
