                "cn": "为了挽回前一天的失败，两人再次以瞬的姿态完成同样的日程。对于展现出与外表相符的成熟举止的瞬，这次老师反而退行到幼儿状态开始撒娇。回过神来的两人，把一切都归咎于夏天。",
