                "en": "",
                "kr": "함께 도망치자며 선생님을 한적한 시골 마을로 데려간 이로하. 시장과 카페, 해변을 함께 거닐며, 사실 오늘이 여름휴가 마지막 날이라 밝히고는 언젠가 함께 떠나자고 제안한다.",
