                "en": "",
                "kr": "혼자서 콧노래를 부르는 걸 선생님에게 들킨 코코로. 선생님은 코코로가 어째서 다른 사람 앞에서 노래 부르는 걸 꺼리는지에 대해 묻고, 코코로는 숨겨 왔던 자신의 비밀에 대해 털어놓는다.",
