                "en": "",
                "kr": "선생님의 실수로 긴급 부상을 하느라, 잠수병에 걸린 코코로. 잠수병으로 인해 정신이 혼미해진 코코로는 저도 모르게 선생님께 의존하고 만다.",
                "jp": "",
                "tw": "",
                "th": ""
