                "en": "",
                "kr": "연락이 끊긴 펜팔 친구에게 편지를 부칠지 망설이는 코토네. 자신감을 잃고 망설이는 코토네를 선생님이 격려해 준다.",
                "jp": "",
                "tw": "",
                "th": ""
