                "kr": "어느 날 갑자기 샬레 건물 외벽을 기어 올라와 샬레에 방문한 리츠. 리츠는 일전에 자신의 조각을 도와주다 옷을 더럽힌 선생을 위한 새 셔츠를 선물로 가져왔다.",
                "jp": "",
                "tw": "",
                "th": ""
