                "en": "",
                "kr": "리츠와 옷 쇼핑을 하기 위해 상점가로 나온 선생. 그런데 길을 잘못 드는 바람에 사장이 손님을 협박하는 어둠의 상점에 발을 들이게 된다. 그렇게 꼼짝 없이 강매를 당할 위기에 처한 그때, 리츠가 나타나는데…….",
