                "cn": "访问千禧年的老师，目击了与同班同学进行微妙氛围对话的茜。在回去的路上，老师遇到了等待着自己的茜，决定一起回去。途中，茜倾诉了与人相处困难的内心想法。听到这些，老师说，虽然没有必须变得亲密的理由，但如果想变得亲密的话会支持她。老师推了茜一把。茜和老师的“变得亲近吧”作战就此开始。",
                "en": "",
                "kr": "밀레니엄에 방문한 선생님은, 아카네의 권유로 그녀의 일상을 바라보게 된다.",
                "jp": "",
                "tw": "",
                "th": ""
